"use client";

import { useEffect, useState } from "react";
import IconButton from "@mui/joy/IconButton";
import PlaylistAddIcon from "@mui/icons-material/PlaylistAdd";
import Checkbox from "@mui/material/Checkbox";
import ListItemText from "@mui/material/ListItemText";
import CircularProgress from "@mui/material/CircularProgress";
import Popover from "@mui/material/Popover";
import MenuList from "@mui/material/MenuList";
import MenuItem from "@mui/material/MenuItem";
import Typography from "@mui/material/Typography";
import FavoriteBorderIcon from "@mui/icons-material/FavoriteBorder";
import FavoriteIcon from "@mui/icons-material/Favorite";

import type { Playlist } from "@/src/types";
import { usePlaylist } from "@/src/hooks/usePlaylist";
import { useFavorites } from "@/src/hooks/useFavorites";
import { Tooltip } from "@mui/material";

interface PlaylistActionMenuProps {
  playlists: Playlist[];
  videoId: number;
}

type InfoKind = "added" | "removed" | "favorite-added" | "favorite-removed";

export default function PlaylistActionMenu({
  playlists,
  videoId,
}: PlaylistActionMenuProps) {
  const { addVideo, deleteVideo } = usePlaylist();
  const {
    favorites,
    fetchAll: fetchAllFavorites,
    addFavorite,
    removeFavoriteForVideo,
    isFavorite,
  } = useFavorites();

  // Ancre Popover (null = fermé)
  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null);

  const [pendingSlug, setPendingSlug] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Etat local : map slug -> bool indiquant si la vidéo est dans la playlist.
  const [checkedMap, setCheckedMap] = useState<Record<string, boolean>>({});

  //Message success qui s’affiche 5 secondes.
  const [infoMessage, setInfoMessage] = useState<string | null>(null);
  const [infoKind, setInfoKind] = useState<InfoKind | null>(null);

  const open = Boolean(anchorEl);
  const id = open ? "playlist-action-popover" : undefined;

  useEffect(() => {
    if (!infoMessage) return;
    const timeout = setTimeout(() => {
      setInfoMessage(null);
      setInfoKind(null);
    }, 5000);
    return () => clearTimeout(timeout);
  }, [infoMessage]);

  // Synchro playlists -> checkedMap
  useEffect(() => {
    const next: Record<string, boolean> = {};
    playlists.forEach((playlist) => {
      const contains =
        playlist.items?.some((item) => item.video.id === videoId) ?? false;
      next[playlist.slug] = contains;
    });
    setCheckedMap(next);
  }, [playlists, videoId]);

  useEffect(() => {
    if (!favorites.length) {
      fetchAllFavorites();
    }
  }, [favorites.length, fetchAllFavorites]);

  const handlePlaylistButtonClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl((current) => (current ? null : event.currentTarget));
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleTogglePlaylist = async (playlist: Playlist) => {
    if (pendingSlug) {
      return;
    }

    const isInPlaylist = checkedMap[playlist.slug] === true;
    setPendingSlug(playlist.slug);
    setError(null);
    setInfoMessage(null);
    setInfoKind(null);

    try {
      if (!isInPlaylist) {
        // Ajouter la vidéo à la playlist
        await addVideo(playlist.slug, { video_id: videoId });
        setCheckedMap((prev) => ({
          ...prev,
          [playlist.slug]: true,
        }));
        setInfoKind("added");
        setInfoMessage(`Vidéo ajoutée à la playlist « ${playlist.title} ».`);
      } else {
        // Retirer la vidéo de la playlist
        await deleteVideo(playlist.slug, { video_id: videoId });
        setCheckedMap((prev) => ({
          ...prev,
          [playlist.slug]: false,
        }));
        setInfoKind("removed");
        setInfoMessage(`Vidéo retirée de la playlist « ${playlist.title} ».`);
      }
    } catch (e) {
      setError(
        e instanceof Error
          ? e.message
          : "Une erreur est survenue lors de la mise à jour de la playlist.",
      );
    } finally {
      setPendingSlug(null);
    }
  };

  const handleToggleFavorite = async () => {
    if (!videoId) {
      return;
    }

    setError(null);
    setInfoMessage(null);
    setInfoKind(null);

    const currentlyFavorite = isFavorite(videoId);

    try {
      if (!currentlyFavorite) {
        const res = await addFavorite(videoId);
        if (res) {
          setInfoKind("favorite-added");
          setInfoMessage("Vidéo ajoutée à vos favoris.");
        }
      } else {
        const ok = await removeFavoriteForVideo(videoId);
        if (ok) {
          setInfoKind("favorite-removed");
          setInfoMessage("Vidéo retirée de vos favoris.");
        }
      }
    } catch (e) {
      setError(
        e instanceof Error
          ? e.message
          : "Une erreur est survenue lors de la mise à jour des favoris.",
      );
    }
  };

  const infoColor =
    infoKind === "added" || infoKind === "favorite-added"
      ? "var(--c--contextuals--text--semantic--success--standard)"
      : infoKind === "removed" || infoKind === "favorite-removed"
        ? "var(--c--contextuals--text--semantic--warning--standard)"
        : "inherit";

  const favorite = isFavorite(videoId);

  return (
    <>
      <div style={{ display: "flex", gap: "0.25rem" }}>
        <Tooltip title="Ajouter la vidéo dans une liste de lecture">
          <IconButton
            aria-describedby={id}
            variant="outlined"
            sx={{
              backgroundColor: "white",
              ":hover": {
                backgroundColor:
                  "var(--c--contextuals--background--semantic--brand--tertiary)",
              },
            }}
            onClick={handlePlaylistButtonClick}
          >
            <PlaylistAddIcon />
          </IconButton>
        </Tooltip>

        <Tooltip title="Ajouter la vidéo en favoris">
          <IconButton
            variant="outlined"
            sx={{
              backgroundColor: "white",
              border: "0px",
              ":hover": {
                backgroundColor:
                  "var(--c--contextuals--background--semantic--brand--tertiary)",
              },
            }}
            onClick={handleToggleFavorite}
          >
            {favorite ? (
              <FavoriteIcon aria-hidden="true" sx={{ color: "red" }} />
            ) : (
              <FavoriteBorderIcon sx={{ color: "red" }} aria-hidden="true" />
            )}
          </IconButton>
        </Tooltip>
      </div>

      {/* Liste des playlists */}
      <Popover
        id={id}
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "right",
        }}
        transformOrigin={{
          vertical: "top",
          horizontal: "right",
        }}
        PaperProps={{
          sx: { minWidth: 260, maxWidth: 320, p: 0 },
        }}
      >
        <div style={{ padding: "0.5rem 1rem" }}>
          <Typography
            variant="subtitle2"
            component="h4"
            sx={{ fontSize: "0.9rem", m: 0 }}
          >
            Ajouter à une liste de lecture
          </Typography>
          {error && (
            <Typography
              variant="body2"
              sx={{
                color: "red",
                fontSize: "0.75rem",
                mt: 0.5,
              }}
            >
              {error}
            </Typography>
          )}
        </div>

        <MenuList
          dense
          disablePadding
          sx={{
            maxHeight: 200,
            overflowY: "auto",
          }}
        >
          {playlists.length === 0 && (
            <MenuItem disabled>Aucune playlist disponible</MenuItem>
          )}

          {playlists.map((playlist) => {
            const checked = checkedMap[playlist.slug] === true;
            const loading = pendingSlug === playlist.slug;

            return (
              <MenuItem
                key={playlist.slug}
                onClick={() => handleTogglePlaylist(playlist)}
                disabled={loading}
                sx={{ display: "flex", alignItems: "center", gap: 1 }}
              >
                {loading ? (
                  <CircularProgress size={18} />
                ) : (
                  <Checkbox
                    size="small"
                    checked={checked}
                    tabIndex={-1}
                    disableRipple
                    sx={{ padding: 0 }}
                  />
                )}
                <ListItemText
                  primary={playlist.title}
                  primaryTypographyProps={{
                    noWrap: true,
                    fontSize: "0.9rem",
                  }}
                />
              </MenuItem>
            );
          })}
        </MenuList>

        {infoMessage && (
          <div
            style={{
              padding: "0.5rem 1rem",
              borderTop: "1px solid #eee",
              fontSize: "0.75rem",
              color: infoColor,
              maxWidth: 280,
              whiteSpace: "normal",
            }}
          >
            {infoMessage}
          </div>
        )}
      </Popover>
    </>
  );
}

"use client";

import {
  Alert,
  Checkbox,
  Button,
  FileUploader,
  VariantType,
} from "@openfun/cunningham-react";
import { useForm } from "react-hook-form";
import { useState } from "react";
import { useRouter } from "next/navigation";
import LinearProgress from "@mui/material/LinearProgress";
import { getRoutes } from "@/src/api/routes";
import { useAuth } from "@/src/context/AuthProvider";
import { authFetch } from "@/src/api/authFetch";
import { requestJson } from "@/src/utils/requestJson";
import { useRequireAuth } from "@/src/hooks/useRequireAuth";
import BackButton from "@/src/components/BackButton/BackButton";
import styles from "./styles.module.css";
import CenteredLoader from "@/src/components/Loader/CenteredLoader";

export const breadcrumbLabel = "Ajouter une vidéo";

type AddVideoFormValues = {
  acceptTerm: boolean;
  videoFile: File | null;
};

export default function AddVideo() {
  const router = useRouter();
  const { accessToken, refresh } = useAuth();
  const { isAuthenticated, isInitializing, mounted } = useRequireAuth();

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
    setValue,
    setError: setFieldError,
    clearErrors,
  } = useForm<AddVideoFormValues>({
    defaultValues: {
      acceptTerm: false,
      videoFile: null,
    },
  });

  const [error, setError] = useState<string | null>(null);
  const [isRedirecting, setIsRedirecting] = useState(false);

  if (!mounted || isInitializing || !isAuthenticated) {
    return <CenteredLoader />;
  }

  const onSubmit = async (data: AddVideoFormValues) => {
    setError(null);
    setIsRedirecting(false);

    try {
      if (!data.videoFile) {
        setFieldError("videoFile", {
          type: "required",
          message: "Veuillez sélectionner un fichier.",
        });
        setError("Veuillez sélectionner un fichier vidéo.");
        return;
      }

      const formData = new FormData();
      formData.append("title", data.videoFile.name);
      formData.append("video_file", data.videoFile);

      const res = await authFetch(getRoutes().video.add, {
        method: "POST",
        body: formData,
        accessToken,
        onRefresh: refresh,
      });
      setIsRedirecting(true);

      // Barre de chargement
      await new Promise<void>((resolve) => {
        requestAnimationFrame(() => {
          setTimeout(resolve, 200);
        });
      });

      const newVid = await requestJson<{ slug: string }>(res);

      router.push(`/video/edit/${newVid.slug}`);
    } catch (err: unknown) {
      setIsRedirecting(false);
      setError(err instanceof Error ? err.message : "Une erreur est survenue.");
    }
  };

  return (
    <div>
      <BackButton label="Retour" />

      <h1>Ajouter une vidéo</h1>

      {/* ---------- Alertes d’erreur ---------- */}
      {error && (
        <Alert canClose type={VariantType.ERROR} aria-live="assertive">
          {error}
        </Alert>
      )}

      {/* ---------- Étape de redirection  ---------- */}
      {isRedirecting ? (
        <div>
          <Alert canClose type={VariantType.SUCCESS} aria-live="polite">
            Votre vidéo est en train d'être téléchargée sur POD. Veuillez ne pas
            fermer la page.
          </Alert>
          <LinearProgress
            sx={{ padding: "5px" }}
            className={styles.linearProgress}
            aria-label="Loading..."
          />
        </div>
      ) : (
        <form
          className={styles.form}
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "1rem",
          }}
          onSubmit={handleSubmit(onSubmit)}
        >
          {/* ---------- Informations générales ---------- */}
          <Alert
            additional={
              <>
                La taille du fichier doit être <b>inférieure à 2 Go</b>.
                <br />
                Le temps d’envoi dépend de la taille de votre fichier et de
                votre vitesse de téléchargement.
                <br />
                <b>
                  Pendant l’envoi de votre fichier, ne fermez pas votre
                  navigateur avant d'avoir reçu un message de succès ou d’échec.
                </b>
              </>
            }
            aria-live="polite"
          >
            Informations
          </Alert>

          {/* ---------- FileUpload ----------*/}
          <FileUploader
            bigText="Choisissez un fichier audio ou vidéo"
            fullWidth={true}
            state={errors.videoFile ? "error" : "default"}
            onFilesChange={(event) => {
              const file = event.target.value?.[0] ?? null;
              setValue("videoFile", file, { shouldValidate: true });
              if (file) {
                clearErrors("videoFile");
              }
            }}
            accept=".3gp, .avi, .divx, .flv, .m2p, .m4v, .mkv,
          .mov, .mp4, .mpeg, .mpg, .mts, .wmv, .mp3,
          .ogg, .wav, .wma, .webm, .ts"
            aria-label="Sélectionner un fichier audio ou vidéo"
            aria-describedby="videoFile-error"
            aria-required="true"
            text={
              errors.videoFile?.message ??
              "Les formats suivants sont supportés : 3gp, avi, divx, flv, m2p, m4v, mkv, mov, mp4, mpeg, mpg, mts, wmv, mp3, ogg, wav, wma, webm, ts."
            }
          />
          {/* Message d’erreur lié au FileUploader */}
          {errors.videoFile && (
            <p
              id="videoFile-error"
              style={{ color: "red", marginTop: "0.25rem" }}
            >
              {errors.videoFile.message}
            </p>
          )}

          {/* ---------- Conditions d’utilisation ---------- */}
          <fieldset className={styles.bloc_terms}>
            <legend>Conditions d’utilisation</legend>

            <p>
              <b>
                Attention ! Assurez‑vous de respecter le code de la propriété
                intellectuelle avant de publier une vidéo :
              </b>
            </p>

            <p>
              Je confirme que je dispose des autorisations nécessaires signées
              par les parties concernées par la publication de ce média, en ce
              compris le consentement relatif au droit à l’image et au
              traitement des données personnelles. Je certifie que l’ensemble
              des personnes concernées ont bénéficié d’une information complète
              relative au traitement de leurs données personnelles, conformément
              aux dispositions des articles 13 et 14 du RGPD.
            </p>

            <Checkbox
              className={styles.bloc_terms_checkbox}
              label="J'atteste de respecter le code de la propriété intellectuelle en publiant ma vidéo."
              fullWidth
              state={errors.acceptTerm ? "error" : "default"}
              aria-describedby="acceptTerm-error"
              aria-required="true"
              {...register("acceptTerm", {
                required: "Veuillez accepter les conditions d'utilisation.",
                validate: (value) =>
                  Boolean(value) ||
                  "Veuillez accepter les conditions d'utilisation.",
              })}
            />
            {/* Message d’erreur lié à la Checkbox */}
            {errors.acceptTerm && (
              <p
                id="acceptTerm-error"
                style={{ color: "red", marginTop: "0.25rem" }}
              >
                {errors.acceptTerm.message}
              </p>
            )}
          </fieldset>

          {/* ---------- Bouton de soumission ---------- */}
          <Button
            type="submit"
            color="success"
            disabled={isSubmitting || isRedirecting}
          >
            Ajouter une vidéo
          </Button>
        </form>
      )}
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import Paper from "@mui/material/Paper";
import { useVideo, useDeleteVideo } from "@/src/hooks/useVideos";
import { useParams } from "next/navigation";
import { useRequireAuth } from "@/src/hooks/useRequireAuth";
import { Alert, Button, VariantType } from "@openfun/cunningham-react";
import styles from "./styles.module.css";
import { useVideoPermissions } from "@/src/hooks/useVideoPermission";
import CenteredLoader from "@/src/components/Loader/CenteredLoader";

export const breadcrumbLabel = "Supprimer la vidéo";

export default function DeleteVideoPage() {
  const router = useRouter();
  const params = useParams();
  const getVideoSlug = Array.isArray(params.slug)
    ? params.slug[0]
    : params.slug;
  const { isAuthenticated, isInitializing, mounted } = useRequireAuth();
  const { data: video, isLoading: useVideoLoading, error } = useVideo(getVideoSlug ?? "");
  const useVideoError = error?.message ?? null;
  const { mutateAsync: deleteVideo } = useDeleteVideo();
  const { isOwnerOrCoOwner } = useVideoPermissions(video ?? null);

  const handleDelete = async () => {
    if (!getVideoSlug) return;
    try {
      await deleteVideo(getVideoSlug);
      router.push("/video");
      router.refresh();
    } catch (err) {
      console.error(err);
    }
  };

  if (!mounted || isInitializing || !isAuthenticated) {
    return <CenteredLoader />;
  }

  return (
    <div className={styles.delete_container}>
      <Paper sx={{ p: 4, maxWidth: 520, width: "100%" }}>
        <h2>Supprimer la vidéo</h2>

        {useVideoLoading && !video && <CenteredLoader />}

        {useVideoError ? (
          <div>
            <Alert type={VariantType.ERROR} className={styles.delete_alert}>
              {useVideoError ?? "Vidéo introuvable."}
            </Alert>
            <Button
              variant="bordered"
              onClick={() => router.back()}
              disabled={useVideoLoading}
            >
              Annuler
            </Button>
          </div>
        ) : !isOwnerOrCoOwner ? (
          <Alert type={VariantType.ERROR} className={styles.delete_alert}>
            Vous ne pouvez pas accéder à cette page
          </Alert>
        ) : video ? (
          <>
            <p>
              Etes-vous sûr.e de vouloir supprimer la vidéo{" "}
              <strong>{video.title}</strong> ? <br />
              Cette action est définitive.
            </p>

            <div className={styles.buttons_action}>
              <Button
                color="brand"
                variant="secondary"
                type="reset"
                onClick={() => router.back()}
                disabled={useVideoLoading}
              >
                Annuler
              </Button>

              <Button
                color="error"
                variant="primary"
                type="button"
                onClick={handleDelete}
                disabled={useVideoLoading}
              >
                Supprimer la vidéo
              </Button>
            </div>
          </>
        ) : null}
      </Paper>
    </div>
  );
}

