type ThemeOption = Theme & {
  depth: number;
  path: string;
};

function buildThemeOptions(themes: Theme[]): ThemeOption[] {
  const walk = (
    themeList: Theme[],
    depth = 0,
    parentPath = "",
  ): ThemeOption[] => {
    return themeList.flatMap((theme) => {
      const path = parentPath ? `${parentPath} / ${theme.title}` : theme.title;
      return [
        { ...theme, depth, path },
        ...walk(theme.children ?? [], depth + 1, path),
      ];
    });
  };
  return walk(themes);
}

