  const tagOptions = useMemo(() => tags.map((t) => t.name).filter(Boolean), [tags]);

  useEffect(() => {
    if (!video) return;
    const initialValues: EditVideoFormValues = {
      title: video.title ?? "",
      description: video.description ?? "",
      status: video.status ?? "PU",
      language: video.language ?? "fr",
