  if (useVideoError || !video) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
        <Alert type={VariantType.ERROR} aria-live="assertive">
          {useVideoError ?? "Impossible de charger cette vidéo."}
