"use client";

import { useState, useEffect } from "react";
import type { MouseEvent } from "react";
import Box from "@mui/material/Box";
import Checkbox from "@mui/material/Checkbox";

import ClickAwayListener from "@mui/material/ClickAwayListener";
import Fade from "@mui/material/Fade";
import FormControlLabel from "@mui/material/FormControlLabel";
import FormGroup from "@mui/material/FormGroup";
import InputAdornment from "@mui/material/InputAdornment";
import ListItemButton from "@mui/material/ListItemButton";
import Paper from "@mui/material/Paper";
import Popper from "@mui/material/Popper";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import useMediaQuery from "@mui/material/useMediaQuery";
import ExpandLessIcon from "@mui/icons-material/ExpandLess";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import SearchIcon from "@mui/icons-material/Search";
import RadioButtonCheckedIcon from "@mui/icons-material/RadioButtonChecked";
import RadioButtonUncheckedIcon from "@mui/icons-material/RadioButtonUnchecked";
import CircularProgress from "@mui/material/CircularProgress";
import { Button } from "@openfun/cunningham-react";
import styles from "./styles.module.css";

export type SelectOption = {
  label: string;
  value: string;
};

export type FilterDropdownProps = {
  title: string;
  options: SelectOption[];
  selectedValues: string[];
  onChange: (newValues: string[]) => void;
  multiple?: boolean;
  onSearchChange?: (search: string) => void;
  searchValue?: string;
  isAsync?: boolean;
  loading?: boolean;
};

export default function FilterDropdown({
  title,
  options,
  selectedValues,
  onChange,
  multiple = true,
  onSearchChange,
  searchValue,
  isAsync = false,
  loading = false,
}: FilterDropdownProps) {
  const [open, setOpen] = useState(false);
  const [localSearchText, setLocalSearchText] = useState("");
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const isMobile = useMediaQuery("(max-width: 600px)");

  // Local selected state for deferred multi-select updates (Vinted-style commit button)
  const [localSelectedValues, setLocalSelectedValues] = useState<string[]>(selectedValues);

  useEffect(() => {
    setLocalSelectedValues(selectedValues);
  }, [selectedValues]);

  const searchText = onSearchChange ? (searchValue ?? "") : localSearchText;

  const matchingOptions = onSearchChange
    ? options
    : options.filter((option) =>
        option.label.toLowerCase().includes(searchText.toLowerCase()),
      );

  const matchedSelected = matchingOptions.filter((o) =>
    multiple ? localSelectedValues.includes(o.value) : selectedValues.includes(o.value)
  );

  const matchedUnselected = matchingOptions.filter((o) =>
    multiple ? !localSelectedValues.includes(o.value) : !selectedValues.includes(o.value)
  );

  // Take the first 50 unselected to avoid performance issues (10k+ tags)
  const displayUnselected = isAsync ? matchedUnselected : matchedUnselected.slice(0, 50);

  const filteredOptions = [...matchedSelected, ...displayUnselected];

  const selectedCount = selectedValues.length;
  const selectedLabel =
    !multiple && selectedCount === 1
      ? options.find((option) => option.value === selectedValues[0])?.label || selectedValues[0]
      : null;

  const handleClick = (event: MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
    if (!open) {
      setLocalSelectedValues(selectedValues);
      setLocalSearchText("");
    }
    setOpen((currentOpen) => !currentOpen);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleToggle = (optionValue: string) => {
    if (!multiple) {
      onChange(selectedValues.includes(optionValue) ? [] : [optionValue]);
      setOpen(false);
      return;
    }

    if (localSelectedValues.includes(optionValue)) {
      setLocalSelectedValues(localSelectedValues.filter((value) => value !== optionValue));
    } else {
      setLocalSelectedValues([...localSelectedValues, optionValue]);
    }
  };

  const popperWidth = isMobile && anchorEl ? anchorEl.clientWidth : 260;

  return (
    <Box className={styles.filterItem}>
      <ListItemButton
        onClick={handleClick}
        className={`${styles.filterButton} ${selectedCount > 0 ? styles.active : ""}`}
        aria-expanded={open}
      >
        <Typography
          variant="body2"
          fontWeight={selectedCount > 0 ? 600 : 500}
          noWrap
          sx={{
            color: selectedCount > 0 ? "var(--c--globals--colors--brand--main)" : "inherit",
          }}
        >
          {multiple
            ? selectedCount > 0
              ? `${title} (${selectedCount})`
              : title
            : selectedCount === 1 && selectedLabel
              ? `${title} : ${selectedLabel}`
              : title}
        </Typography>
        {open ? (
          <ExpandLessIcon fontSize="small" sx={{ color: selectedCount > 0 ? "var(--c--globals--colors--brand--main)" : "inherit", ml: "auto" }} />
        ) : (
          <ExpandMoreIcon fontSize="small" sx={{ color: selectedCount > 0 ? "var(--c--globals--colors--brand--main)" : "inherit", ml: "auto" }} />
        )}
      </ListItemButton>

      <Popper
        open={open}
        anchorEl={anchorEl}
        placement="bottom-start"
        transition
        sx={{
          zIndex: 1300,
          width: popperWidth,
          maxWidth: "100vw",
        }}
        modifiers={[
          {
            name: "offset",
            options: {
              offset: [0, 8],
            },
          },
          {
            name: "preventOverflow",
            options: {
              padding: 16,
            },
          },
        ]}
      >
        {({ TransitionProps }) => (
          <Fade {...TransitionProps} timeout={250}>
            <Paper elevation={8} className={styles.filterMenu}>
              <ClickAwayListener onClickAway={handleClose}>
                <Box>
                  {(options.length > 0 || onSearchChange || isAsync) && (
                    <TextField
                      fullWidth
                      variant="outlined"
                      placeholder="Rechercher..."
                      size="small"
                      value={searchText}
                      onChange={(event) => {
                        const val = event.target.value;
                        if (onSearchChange) onSearchChange(val);
                        else setLocalSearchText(val);
                      }}
                      InputProps={{
                        startAdornment: (
                          <InputAdornment position="start">
                            <SearchIcon fontSize="small" />
                          </InputAdornment>
                        ),
                        endAdornment: loading ? (
                          <InputAdornment position="end">
                            <CircularProgress color="inherit" size={20} />
                          </InputAdornment>
                        ) : null,
                      }}
                      sx={{ mb: 1.5 }}
                    />
                  )}

                  <FormGroup className={styles.filterOptions}>
                    {filteredOptions.map((option) => (
                      <FormControlLabel
                        key={option.value}
                        control={
                          multiple ? (
                            <Checkbox
                              checked={localSelectedValues.includes(option.value)}
                              onChange={() => handleToggle(option.value)}
                              size="small"
                            />
                          ) : (
                            <Checkbox
                              checkedIcon={<RadioButtonCheckedIcon />}
                              icon={<RadioButtonUncheckedIcon />}
                              checked={selectedValues.includes(option.value)}
                              onChange={() => handleToggle(option.value)}
                              size="small"
                            />
                          )
                        }
                        label={option.label}
                        className={styles.filterOption}
                      />
                    ))}

                    {!loading && filteredOptions.length === 0 && (
                      <Typography color="text.secondary" variant="body2" sx={{ p: 1 }}>
                        Aucun résultat
                      </Typography>
                    )}
                  </FormGroup>

                  {multiple && (
                    <Box
                      sx={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        mt: 1.5,
                        pt: 1.5,
                        borderTop: "1px solid rgba(0, 0, 0, 0.08)",
                        gap: "8px",
                      }}
                    >
                      <Button
                        onClick={() => {
                          setLocalSelectedValues([]);
                        }}
                        variant="tertiary"
                        size="small"
                        disabled={localSelectedValues.length === 0}
                      >
                        Effacer
                      </Button>
                      <Button
                        onClick={() => {
                          onChange(localSelectedValues);
                          setOpen(false);
                        }}
                        variant="primary"
                        size="small"
                      >
                        Afficher
                      </Button>
                    </Box>
                  )}
                </Box>
              </ClickAwayListener>
            </Paper>
          </Fade>
        )}
      </Popper>
    </Box>
  );
}

"use client";

import { useMemo, useCallback } from "react";
import Box from "@mui/material/Box";
import Chip from "@mui/material/Chip";
import InputAdornment from "@mui/material/InputAdornment";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import CloseIcon from "@mui/icons-material/Close";
import SearchIcon from "@mui/icons-material/Search";
import { CURSUS_OPTIONS } from "@/src/constants/cursus";
import { getUserDisplayName } from "@/src/constants/user";
import type { Discipline, Tags, Type, User } from "@/src/types";
import { Button } from "@openfun/cunningham-react";
import styles from "./styles.module.css";
import useMediaQuery from "@mui/material/useMediaQuery";
import { useUsers } from "@/src/hooks/useUsers";
import { useChannel } from "@/src/hooks/useChannel";
import { useTags as useTagsHook } from "@/src/hooks/useTags";
import FilterDropdown from "./FilterDropdown";
import AsyncFilterDropdown from "./AsyncFilterDropdown";

export type VideoFiltersValue = {
  search: string;
  ordering: string;
  channel: number | null;
  ownerUsernames: string[];
  typeSlugs: string[];
  disciplineIds: number[];
  cursus: string[];
  tagSlugs: string[];
  page: number;
};

type Props = {
  value: VideoFiltersValue;
  users: User[];
  types: Type[];
  disciplines: Discipline[];
  tags: Tags[];
  channels: number[];
  showUserFilter?: boolean;
  showChannelFilter?: boolean;
  onChange: (value: VideoFiltersValue) => void;
};

type SelectOption = {
  label: string;
  value: string;
};

const ORDERING_OPTIONS: SelectOption[] = [
  { label: "Plus récentes", value: "-created_at" },
  { label: "Plus anciennes", value: "created_at" },
  { label: "Titre A-Z", value: "title" },
  { label: "Titre Z-A", value: "-title" },
];

const haveSameValues = <T extends string | number>(
  currentValues: T[],
  nextValues: T[],
) =>
  currentValues.length === nextValues.length &&
  currentValues.every(
    (currentValue, index) => currentValue === nextValues[index],
  );

const normalizeValues = <T extends string | number>(values: T[]) =>
  [...values].sort((first, second) =>
    String(first).localeCompare(String(second)),
  );

const sortByOptions = (values: string[], options: SelectOption[]) => {
  const orderByValue = new Map(
    options.map((option, index) => [option.value, index]),
  );

  return [...values].sort(
    (first, second) =>
      (orderByValue.get(first) ?? Number.MAX_SAFE_INTEGER) -
      (orderByValue.get(second) ?? Number.MAX_SAFE_INTEGER),
  );
};

const FilterChip = ({
  label,
  onDelete,
}: {
  label: string;
  onDelete: () => void;
}) => (
  <Chip
    label={label}
    onDelete={onDelete}
    deleteIcon={<CloseIcon />}
    size="small"
    sx={{
      m: 0.25,
      borderRadius: "16px",
      backgroundColor: "rgba(0, 0, 0, 0.06)",
      fontWeight: 500,
      "& .MuiChip-deleteIcon": {
        color: "rgba(0, 0, 0, 0.4)",
        "&:hover": {
          color: "rgba(0, 0, 0, 0.7)",
        },
      },
    }}
  />
);

export const INITIAL_VIDEO_FILTERS: VideoFiltersValue = {
  search: "",
  ordering: "",
  channel: null,
  ownerUsernames: [],
  typeSlugs: [],
  disciplineIds: [],
  cursus: [],
  tagSlugs: [],
  page: 1,
};

export default function VideoFilters({
  value,
  users,
  types,
  disciplines,
  tags,
  channels,
  showUserFilter = true,
  showChannelFilter = true,
  onChange,
}: Props) {
  const isMobile = useMediaQuery("(max-width: 600px)");

  const { fetchAll: fetchUsers } = useUsers();
  const { fetchAll: fetchChannels } = useChannel();
  const { fetchAll: fetchTags } = useTagsHook();

  const fetchUsersOptions = useCallback(
    async (search: string) => {
      const usersList = await fetchUsers(search);
      return usersList.map((u) => ({
        label: getUserDisplayName(u),
        value: u.username,
      }));
    },
    [fetchUsers]
  );

  const fetchChannelsOptions = useCallback(
    async (search: string) => {
      const channelsList = await fetchChannels({ search });
      return channelsList.map((c) => ({
        label: c.title,
        value: String(c.id),
      }));
    },
    [fetchChannels]
  );

  const fetchTagsOptions = useCallback(
    async (search: string) => {
      const tagsList = await fetchTags(search);
      return tagsList.map((t) => ({
        label: t.name,
        value: t.slug,
      }));
    },
    [fetchTags]
  );

  const typeOptions = useMemo(
    () =>
      types.map((type) => ({
        label: type.title,
        value: type.slug,
      })),
    [types],
  );

  const disciplineOptions = useMemo<SelectOption[]>(
    () =>
      disciplines.map((discipline) => ({
        label: discipline.title,
        value: String(discipline.id),
      })),
    [disciplines],
  );

  const selectedChannelLabel = value.channel ? `Chaîne ${value.channel}` : null;

  const selectedUsers = useMemo(() => {
    return value.ownerUsernames.map((username) => {
      const fullUser = users.find((u) => u.username === username);
      return {
        label: fullUser ? getUserDisplayName(fullUser) : username,
        value: username,
      };
    });
  }, [value.ownerUsernames, users]);

  const selectedTypes = typeOptions.filter((option) =>
    value.typeSlugs.includes(String(option.value)),
  );

  const selectedDisciplines = disciplineOptions.filter((option) =>
    value.disciplineIds.includes(Number(option.value)),
  );

  const selectedCursus = CURSUS_OPTIONS.filter((option) =>
    value.cursus.includes(option.value),
  );

  const selectedTags = useMemo(() => {
    return value.tagSlugs.map((slug) => {
      const fullTag = tags.find((t) => t.slug === slug);
      return {
        label: fullTag ? fullTag.name : slug,
        value: slug,
      };
    });
  }, [value.tagSlugs, tags]);

  const removeValue = <T extends string | number>(
    list: T[],
    target: T,
  ): T[] => {
    return list.filter((item) => item !== target);
  };

  const appliedFiltersCount =
    (value.search.trim() ? 1 : 0) +
    (value.channel ? 1 : 0) +
    (showUserFilter ? value.ownerUsernames.length : 0) +
    selectedTypes.length +
    selectedDisciplines.length +
    selectedCursus.length +
    selectedTags.length;

  return (
    <div className={styles.filtersContent}>
      {/* Vinted-style horizontal scrollable pill bar */}
      <div className={styles.row}>
        {/* Unified inline search bar */}
        <TextField
          id="video-filters-search"
          size="small"
          placeholder="Rechercher une vidéo..."
          value={value.search}
          onChange={(event) => {
            const nextSearch =
              typeof event.target.value === "string"
                ? event.target.value
                : "";

            if (nextSearch === value.search) {
              return;
            }

            onChange({
              ...value,
              search: nextSearch,
            });
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon fontSize="small" />
              </InputAdornment>
            ),
          }}
          sx={{
            minWidth: isMobile ? "100%" : "220px",
            "& .MuiOutlinedInput-root": {
              borderRadius: "9999px",
              backgroundColor: "#fff",
              paddingLeft: "12px",
            },
          }}
        />

        {/* Tri/Ordering Pill (Single selection) */}
        <FilterDropdown
          title="Tri"
          options={ORDERING_OPTIONS}
          selectedValues={value.ordering ? [value.ordering] : []}
          multiple={false}
          onChange={(nextValues) => {
            const nextOrdering = nextValues[0] ?? "";
            if (nextOrdering === value.ordering) return;
            onChange({
              ...value,
              ordering: nextOrdering,
            });
          }}
        />

        {/* Channel Pill (Async single select) */}
        {showChannelFilter && (
          <AsyncFilterDropdown
            title="Chaîne"
            selectedValues={value.channel ? [String(value.channel)] : []}
            fetchOptions={fetchChannelsOptions}
            multiple={false}
            onChange={(nextValues) => {
              const nextChannel = nextValues[0] ? Number(nextValues[0]) : null;
              if (nextChannel === value.channel) return;
              onChange({ ...value, channel: nextChannel });
            }}
          />
        )}

        {/* User Pill (Async multi select) */}
        {showUserFilter && (
          <AsyncFilterDropdown
            title="Auteur"
            selectedValues={value.ownerUsernames}
            fetchOptions={fetchUsersOptions}
            onChange={(nextOwnerUsernames) => {
              if (haveSameValues(value.ownerUsernames, nextOwnerUsernames)) return;
              onChange({ ...value, ownerUsernames: nextOwnerUsernames });
            }}
          />
        )}

        {/* Types Pill (Multi select) */}
        <FilterDropdown
          title="Types"
          options={typeOptions}
          selectedValues={value.typeSlugs}
          onChange={(nextTypeSlugs) => {
            if (haveSameValues(value.typeSlugs, nextTypeSlugs)) return;
            onChange({
              ...value,
              typeSlugs: nextTypeSlugs,
            });
          }}
        />

        {/* Disciplines Pill (Multi select) */}
        <FilterDropdown
          title="Disciplines"
          options={disciplineOptions}
          selectedValues={value.disciplineIds.map(String)}
          onChange={(nextValues) => {
            const nextDisciplineIds = nextValues.map(Number);
            if (haveSameValues(value.disciplineIds, nextDisciplineIds)) return;
            onChange({
              ...value,
              disciplineIds: nextDisciplineIds,
            });
          }}
        />

        {/* Cursus Pill (Multi select) */}
        <FilterDropdown
          title="Cursus"
          options={CURSUS_OPTIONS}
          selectedValues={value.cursus}
          onChange={(nextCursus) => {
            if (haveSameValues(value.cursus, nextCursus)) return;
            onChange({
              ...value,
              cursus: nextCursus,
            });
          }}
        />

        {/* Mots-clés Pill (Async multi select) */}
        <AsyncFilterDropdown
          title="Mots-clés"
          selectedValues={value.tagSlugs}
          fetchOptions={fetchTagsOptions}
          onChange={(nextTagSlugs) => {
            if (haveSameValues(value.tagSlugs, nextTagSlugs)) return;
            onChange({
              ...value,
              tagSlugs: nextTagSlugs,
            });
          }}
        />
      </div>

      {/* Selected Chips Row with Clean Clear Action */}
      {appliedFiltersCount > 0 && (
        <Box
          sx={{
            display: "flex",
            flexWrap: "wrap",
            alignItems: "center",
            justifyContent: "space-between",
            mt: 2,
            gap: "12px",
            pt: 1.5,
            borderTop: "1px solid rgba(0, 0, 0, 0.12)",
          }}
        >
          <Box className={styles.chips}>
            {value.search.trim() && (
              <FilterChip
                label={`Recherche : ${value.search}`}
                onDelete={() => onChange({ ...value, search: "" })}
              />
            )}

            {showChannelFilter && value.channel && (
              <FilterChip
                label={selectedChannelLabel ?? `Chaîne : ${value.channel}`}
                onDelete={() => onChange({ ...value, channel: null })}
              />
            )}

            {showUserFilter && selectedUsers.map((u) => (
              <FilterChip
                key={`user-${u.value}`}
                label={`Auteur : ${u.label}`}
                onDelete={() =>
                  onChange({
                    ...value,
                    ownerUsernames: removeValue(value.ownerUsernames, u.value),
                  })
                }
              />
            ))}

            {selectedTypes.map((option) => (
              <FilterChip
                key={`type-${option.value}`}
                label={`Type : ${option.label}`}
                onDelete={() =>
                  onChange({
                    ...value,
                    typeSlugs: removeValue(
                      value.typeSlugs,
                      String(option.value),
                    ),
                  })
                }
              />
            ))}

            {selectedDisciplines.map((option) => (
              <FilterChip
                key={`discipline-${option.value}`}
                label={`Discipline : ${option.label}`}
                onDelete={() =>
                  onChange({
                    ...value,
                    disciplineIds: removeValue(
                      value.disciplineIds,
                      Number(option.value),
                    ),
                  })
                }
              />
            ))}

            {selectedCursus.map((option) => (
              <FilterChip
                key={`cursus-${option.value}`}
                label={`Cursus : ${option.label}`}
                onDelete={() =>
                  onChange({
                    ...value,
                    cursus: removeValue(value.cursus, option.value),
                  })
                }
              />
            ))}

            {selectedTags.map((option) => (
              <FilterChip
                key={`tag-${option.value}`}
                label={`Mot-clé : ${option.label}`}
                onDelete={() =>
                  onChange({
                    ...value,
                    tagSlugs: removeValue(
                      value.tagSlugs,
                      String(option.value),
                    ),
                  })
                }
              />
            ))}
          </Box>

          <Button
            onClick={() => onChange(INITIAL_VIDEO_FILTERS)}
            variant="tertiary"
            size="small"
            style={{ fontWeight: 600, fontSize: "0.85rem" }}
          >
            Effacer les filtres
          </Button>
        </Box>
      )}
    </div>
  );
}

"use client";

import {
  useContext,
  createContext,
  useEffect,
  useMemo,
  useState,
  useRef,
} from "react";
import { requestJson } from "../utils/requestJson";
import { authFetch } from "../api/authFetch";
import type { User } from "@/src/types";
import { getRoutes } from "../api/routes";
import { useAppConfig } from "../hooks/useAppConfig";

import { useRouter } from "next/navigation";
type AuthConfig = {
  use_local: boolean;
  use_cas: boolean;
  use_shibboleth: boolean;
  use_oidc: boolean;
};

type LogoutInfo = {
  local: string | null;
  cas: string | null;
  shibboleth: string | null;
  oidc: string | null;
};

type AuthContextValue = {
  accessToken: string | null;
  refreshToken: string | null;
  isAuthenticated: boolean;
  isInitializing: boolean;
  user: User | null;
  authConfig: AuthConfig | null;
  logoutUrl: string;
  isAuthDataLoading: boolean;
  logIn: (username: string, password: string) => Promise<void>;
  logout: () => void;
  refresh: () => Promise<string | null>;
  verify: () => Promise<boolean>;
  reloadAuthData: () => Promise<void>;
};
type AuthProviderProps = {
  children: React.ReactNode;
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

const ACCESS_TOKEN_KEY = "auth_access_token";
const REFRESH_TOKEN_KEY = "auth_refresh_token";

const getConfigFlag = (config: Record<string, unknown> | null, key: string) => {
  if (!config) return false;
  const lowerValue = config[key];
  if (typeof lowerValue === "boolean") return lowerValue;
  const upperValue = config[key.toUpperCase()];
  if (typeof upperValue === "boolean") return upperValue;
  return false;
};

const normalizeAuthConfig = (
  config: Record<string, unknown> | null,
): AuthConfig | null => {
  if (!config) return null;

  return {
    use_local: getConfigFlag(config, "use_local"),
    use_cas: getConfigFlag(config, "use_cas"),
    use_shibboleth: getConfigFlag(config, "use_shibboleth"),
    use_oidc: getConfigFlag(config, "use_oidc"),
  };
};

// Priorite: local > cas > shibboleth > oidc.
const resolveLogoutUrl = (
  config: AuthConfig | null,
  logoutInfo: LogoutInfo | null,
) => {
  if (!config || !logoutInfo) return "/";
  if (config.use_local) return logoutInfo.local || "/";
  if (config.use_cas) return logoutInfo.cas || "/";
  if (config.use_shibboleth) return logoutInfo.shibboleth || "/";
  if (config.use_oidc) return logoutInfo.oidc || "/";
  return "/";
};

export default function AuthProvider(props: AuthProviderProps) {
  const { config } = useAppConfig();

  // Router Next.js pour pouvoir rediriger en cas d'expiration de session
  const router = useRouter();

  // Permet d'éviter de déclencher plusieurs fois de suite
  // la logique de "session expirée" lorsque plusieurs requêtes
  // concurrentes échouent en même temps.
  const hasForcedLogoutRef = useRef(false);

  const [accessToken, setAccessToken] = useState<string | null>(null);
  const [refreshToken, setRefreshToken] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [user, setUser] = useState<User | null>(null);
  const [logoutInfo, setLogoutInfo] = useState<LogoutInfo | null>(null);
  const [isAuthDataLoading, setIsAuthDataLoading] = useState(false);

  // Dérivation directe — pas besoin d'effect pour ça
  const authConfig = useMemo(
    () => normalizeAuthConfig((config as Record<string, unknown>) ?? null),
    [config],
  );

  const logoutUrl = useMemo(
    () => resolveLogoutUrl(authConfig, logoutInfo),
    [authConfig, logoutInfo],
  );



  const persistTokens = (token: string | null, refreshValue: string | null) => {
    setAccessToken(token);
    setRefreshToken(refreshValue);

    // Si on enregistre de nouveaux tokens (login ou refresh réussi),
    // on réinitialise le flag pour permettre une future détection
    // d'expiration de session.
    if (token && refreshValue) {
      hasForcedLogoutRef.current = false;
    }
    token
      ? localStorage.setItem(ACCESS_TOKEN_KEY, token)
      : localStorage.removeItem(ACCESS_TOKEN_KEY);
    refreshValue
      ? localStorage.setItem(REFRESH_TOKEN_KEY, refreshValue)
      : localStorage.removeItem(REFRESH_TOKEN_KEY);
  };

  const logout = () => {
    persistTokens(null, null);
    setUser(null);
    setLogoutInfo(null);
  };

  /**
   * Déconnexion forcée + redirection vers la page de login
   * lorsqu'on détecte une expiration de session (échec du refresh).
   *
   * On protège cette logique avec un ref pour ne pas la déclencher
   * plusieurs fois en cas de multiples requêtes concurrentes qui
   * échouent en même temps.
   */
  const forceLogoutAndRedirectToLogin = () => {
    if (hasForcedLogoutRef.current) {
      return;
    }

    hasForcedLogoutRef.current = true;

    // Nettoyage local de l'état d'authentification
    logout();

    // Redirection vers la page de login en conservant la page courante
    // pour pouvoir y revenir après reconnexion.
    const currentPath =
      typeof window !== "undefined"
        ? window.location.pathname + window.location.search
        : "/";

    router.replace(
      `/login?reason=auth&redirect=${encodeURIComponent(currentPath)}`,
    );
  };

  const verify = async (token?: string | null) => {
    const tokenToVerify = token ?? accessToken;
    if (!tokenToVerify) return false;
    try {
      await requestJson(getRoutes().auth.token.verify, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: tokenToVerify }),
      });
      return true;
    } catch {
      return false;
    }
  };

  const refresh = async (token?: string | null) => {
    const tokenToRefresh = token ?? refreshToken;
    if (!tokenToRefresh) return null;
    try {
      const data = await requestJson<{ access: string }>(
        getRoutes().auth.token.refresh,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh: tokenToRefresh }),
        },
      );
      const newAccess = data.access;
      persistTokens(newAccess, tokenToRefresh);
      return newAccess;
    } catch {
      // Si le refresh échoue (401 typiquement), on considère que la
      // session est expirée : on force la déconnexion et on redirige
      // l'utilisateur vers la page de login.
      forceLogoutAndRedirectToLogin();
      return null;
    }
  };

  const loadAuthDataWithToken = async (
    token: string,
    onRefresh?: () => Promise<string | null>,
  ) => {
    setIsAuthDataLoading(true);
    try {
      const [userRes, logoutInfoRes] = await Promise.all([
        authFetch(getRoutes().auth.user.data, {
          accessToken: token,
          onRefresh,
        }),
        authFetch(getRoutes().auth.user.logout, {
          accessToken: token,
          onRefresh,
        }),
      ]);

      const [userData, logoutInfoData] = await Promise.all([
        requestJson<User>(userRes),
        requestJson<LogoutInfo>(logoutInfoRes),
      ]);
      setUser(userData);
      setLogoutInfo(logoutInfoData);
    } catch {
      setUser(null);
      setLogoutInfo(null);
    } finally {
      setIsAuthDataLoading(false);
    }
  };

  const reloadAuthData = async () => {
    if (!accessToken) {
      setUser(null);
      setLogoutInfo(null);
      return;
    }
    await loadAuthDataWithToken(accessToken, refresh);
  };

  const logIn = async (username: string, password: string) => {
    const data = await requestJson<{ access: string; refresh: string }>(
      getRoutes().auth.token.create,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      },
    );

    persistTokens(data.access, data.refresh);
    await loadAuthDataWithToken(data.access, () => refresh(data.refresh));
  };

  useEffect(() => {
    const init = async () => {
      const storedAccess = localStorage.getItem(ACCESS_TOKEN_KEY);
      const storedRefresh = localStorage.getItem(REFRESH_TOKEN_KEY);
      setAccessToken(storedAccess);
      setRefreshToken(storedRefresh);

      let validAccess: string | null = storedAccess;

      if (storedAccess) {
        const accessTokenIsValid = await verify(storedAccess);
        if (!accessTokenIsValid && storedRefresh) {
          validAccess = await refresh(storedRefresh);
          if (!validAccess) {
            setIsInitializing(false);
            return;
          }
        }
      } else if (storedRefresh) {
        validAccess = await refresh(storedRefresh);
      }

      if (validAccess) {
        await loadAuthDataWithToken(validAccess, () => refresh(storedRefresh));
      } else {
        setUser(null);
        setLogoutInfo(null);
      }

      setIsInitializing(false);
    };

    init();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const value = useMemo<AuthContextValue>(
    () => ({
      accessToken,
      refreshToken,
      isAuthenticated: Boolean(accessToken),
      isInitializing,
      user,
      authConfig,
      logoutUrl,
      isAuthDataLoading,
      logIn,
      logout,
      refresh,
      verify,
      reloadAuthData,
    }),
    [
      accessToken,
      refreshToken,
      isInitializing,
      user,
      authConfig,
      logoutUrl,
      isAuthDataLoading,
    ],
  );

  return (
    <AuthContext.Provider value={value}>{props.children}</AuthContext.Provider>
  );
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth doit etre utilise dans AuthProvider.");
  }
  return ctx;
};

